// 楽天の検索結果から上位N件。args.word があればページ内fetchで検索し直す(遷移しない)。
let doc = document;
if (args.word) {
  const r = await fetch("https://search.rakuten.co.jp/search/mall/" + encodeURIComponent(args.word) + "/", { credentials: "include" });
  doc = new DOMParser().parseFromString(await r.text(), "text/html");
}
const cards = [...doc.querySelectorAll("[class*=searchresultitem]")].slice(0, args.n || 5);
return cards.map(c => {
  const a = c.querySelector("a[class*=title-link]");
  return {
    商品: (a?.textContent || "").replace(/\s+/g, " ").trim().slice(0, 45),
    価格: (c.querySelector("[class*=price]")?.textContent || "").trim().slice(0, 14),
    評価: (c.querySelector("[class*=rating]")?.textContent || "").trim().slice(0, 14),
    URL: (a?.getAttribute("href") || "").split("?")[0],
  };
});
